mapper.update:
UPDATE TB_RESPONSE
SET RSPSN_CN = #{dto.response},
    RSPSN_DT = NOW()
WHERE PARENT_SN = #{dto.parentSn}
  AND USER_SN = #{dto.userSn}
  AND DEL_YN = FALSE

mapper.select:
SELECT RSPSN_SN, PARENT_TYPE, PARENT_SN, USER_SN,
       RSPSN_DT, RSPSN_CN, VIEW_CNT, DEL_YN
FROM TB_RESPONSE
WHERE PARENT_SN = #{parentSn}
  AND USER_SN = #{userSn}
  AND DEL_YN = FALSE

SELECT R.RSPSN_SN, R.PARENT_TYPE, R.PARENT_SN, R.USER_SN, U.USER_NM AS userName, R.RSPSN_DT, R.RSPSN_CN, R.VIEW_CNT, R.DEL_YN FROM TB_RESPONSE R LEFT JOIN TB_USER U ON R.USER_SN = U.USER_SN LEFT JOIN TB_SURVEY S ON R.PARENT_SN = S.SRVY_SN WHERE R.PARENT_SN = #{parentSn} AND R.DEL_YN = FALSE
AND S.CO_SN = #{coSn}
AND S.COHORT_SN = #{cohortSn}
ORDER BY R.RSPSN_DT DESC
